section.p:
To create a hook handler add-on, follow these steps:

Add oxygen-ai-positron-api as a provided dependency
            in your plugin project's
              pom.xml:<dependency>
  <groupId>com.oxygenxml</groupId>
  <artifactId>oxygen-ai-positron-api</artifactId>
  <version>8.3.0</version>
  <scope>compile</scope>
</dependency>
The artifact is published at https://oxygenxml.com/maven/. Add the repository to your
                pom.xml (if it is not already
              present):<repository>
  <id>oxygen-public-repo</id>
  <url>https://www.oxygenxml.com/maven/</url>
</repository>

Implement the
            com.oxygenxml.positron.api.hook.AIHooksHandler interface in your
          plugin's libraries. The single method eventOccurred(String eventName, String
            payloadJson) is called for every hook event. eventName is the
          string identifier of the event (for example, beforeShellExecution);
            payloadJson is the JSON serialization (snake_case keys) of the
          event-specific payload, which you can deserialize into the matching
            BaseHookPayload subclass using Jackson to access its fields. Throw an
            AIHookVetoException from this method to veto a blocking event
          and prevent the associated action from
          running.package my.pack;

import java.util.List;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.oxygenxml.positron.api.hook.AIHookEvent;
import com.oxygenxml.positron.api.hook.AIHookVetoException;
import com.oxygenxml.positron.api.hook.AIHooksHandler;
import com.oxygenxml.positron.api.hook.payload.BeforeShellExecutionPayload;

/**
 * Hook handler that blocks shell commands considered dangerous for
 * a documentation project (destructive file operations, package
 * installations, and network-fetching utilities).
 */
public class ShellGuardHooksHandler implements AIHooksHandler {

  private static final ObjectMapper MAPPER = new ObjectMapper();

  private static final List<String> BLOCKED_PATTERNS = List.of(
      "rm ",  "rmdir", "del ",  "rd ",
      "npm install", "pip install", "mvn install",
      "curl", "wget"
  );

  @Override
  public void eventOccurred(String eventName, String payloadJson) throws AIHookVetoException {
    if (AIHookEvent.BEFORE_SHELL_EXECUTION == AIHookEvent.fromEventName(eventName)) {
      try {
        BeforeShellExecutionPayload data =
            MAPPER.readValue(payloadJson, BeforeShellExecutionPayload.class);
        blockDangerousCommands(data);
      } catch (Exception e) {
        // log and continue — deserialization failures must not block the action
      }
    }
  }

  private void blockDangerousCommands(BeforeShellExecutionPayload data) throws AIHookVetoException {
    String command = data.getCommand();
    if (command == null) {
      return;
    }
    String lowerCommand = command.toLowerCase();
    for (String pattern : BLOCKED_PATTERNS) {
      if (lowerCommand.contains(pattern)) {
        throw new AIHookVetoException(
            "Shell command blocked by policy: '" + command + "'. "
            + "Matched restricted pattern: '" + pattern + "'."
        );
      }
    }
  }
}

In the plugin descriptor file, declare the extension point
            that points to your implementation:
            <extension type="AIHooksHandler" class="my.pack.ShellGuardHooksHandler"/>

The following tables list all hook events grouped by category.
        Blocking events can be vetoed by throwing an AIHookVetoException;
        fire-and-forget events are informational only.
